MATCH (e:Equipment)-[:measured_by]->(s:PlantItem), (f:ProcessInstrumentationFunction {tag: 'TI-361046'})
WHERE s.loop_tag = f.loop_tag
RETURN DISTINCT e.tag AS tag ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-37302B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'EA-6501'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet
ORDER BY sheet;

MATCH (a:PlantItem {tag: 'TK-27704'}), (b:PlantItem {tag: 'P-27702'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-301'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'K-14101'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'E-25201'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'TK-27704'}), (b:PlantItem {tag: 'P-27702'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN size([n IN nodes(p) WHERE n:Valve]) AS valve_count;

MATCH (a:PlantItem {tag: 'H-34201'}), (b:PlantItem {tag: 'E-34201'}), (r:PlantItem {tag: 'R-34201'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y <> r)+ (b)
} AS reachable

MATCH (v:PlantItem:SwingCheckValve {unit_id: '332'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-34201'}), (b:PlantItem {tag: 'E-34201'}), (r:PlantItem {tag: 'R-34201'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         (a) ((x)-[:line_to]->(y) WHERE x <> r AND y <> r)+ (b)
       } AS reachable

MATCH (v:PlantItem {tag: 'V-9701'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'TI-54071'})
RETURN DISTINCT e.tag AS tag
