RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (tank:PlantItem {tag: 'TK-20604'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'TIC-463028'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve {tag: 'V-35501'})-[:line_to*1..]->(u:PlantItem:Equipment)
RETURN DISTINCT u.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:CentrifugalPump {unit_id: '284'})
RETURN p.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-11201'}), (b:PlantItem {tag: 'T-11301'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'EA-46801'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'H-45701'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'K-10701'}), (b:PlantItem {tag: 'R-10601'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem WHERE x.tag <> 'E-10601')-[:line_to]->(y:PlantItem WHERE y.tag <> 'E-10601'))+ (b)
} AS reachable_without_E-10601

MATCH (anchor:PlantItem {tag: 'V-1101'}), (v:PlantItem:Valve)-[:line_to]-(anchor), (loop:ProcessControlFunction)-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(v)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-28403'}), (b:PlantItem {tag: 'EJ-28403'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (t:PlantItem {tag: 'T-44201'}), (v:Valve), (loop:ProcessControlFunction)
WHERE ((t)-[:line_to]->(v) OR (v)-[:line_to]->(t))
  AND EXISTS {
    (loop)-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v)
  }
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-40601'}), (b:PlantItem {tag: 'P-40901'})
RETURN EXISTS {
  (a)-[:line_to*1..]->(b)
  WHERE NONE (n IN [x IN [(a)-[:line_to*0..]->(b) | x] WHERE x.tag = 'TK-40802'] WHERE n = b)
} AS reachable_without_TK_40802

MATCH (a:PlantItem {tag: 'E-40601'}), (b:PlantItem {tag: 'P-40901'})
RETURN a.tag AS source_tag, b.tag AS target_tag, EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'TK-40802' AND y.tag <> 'TK-40802')+ (b)
} AS reachable_without_TK_40802

MATCH (a:PlantItem {tag: 'P-11502A'}), (b:PlantItem {tag: 'P-11801'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-15701A'}), (b:PlantItem {tag: 'EA-16201'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'P-15801B')+ (b)
} AS reachable, a.tag AS source_tag, b.tag AS destination_tag

MATCH (a:PlantItem {tag: 'E-16901'}), (b:PlantItem {tag: 'F-17502'}), (blocked:PlantItem {tag: 'GTV-173009'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> blocked)+ (b)
       } AS can_flow_without_blocked_valve

MATCH (a:PlantItem {tag: 'P-21601'}), (b:PlantItem {tag: 'E-24901'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS valve_tags;

MATCH (a:PlantItem {tag: 'P-37301C'}), (b:PlantItem {tag: 'E-38901'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'E-38101')
       } AS can_flow

MATCH (:PlantItem:Valve {tag: 'GTV-210026'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'BV-59001'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem:Valve {tag: 'GTV-82009'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction:PlantItem {loop_tag: 'FIC-24008'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem {loop_tag: 'LSHH-12006'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:CentrifugalPump {unit_id: '284'})
RETURN p.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:SwingCheckValve {unit_id: '332'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:AngleBallValve {unit_id: '305'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'E-25201'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'H-33401'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-23702A'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (k:PlantItem {tag: 'K-10701'}), (v:PlantItem:Valve)
WHERE EXISTS { (k)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (k:PlantItem {tag: 'K-6701'}), (v:Valve)
WHERE EXISTS { (k)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-16001B'}), (v:Valve)
WHERE v.tag IS NOT NULL
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (f:PlantItem {tag: 'F-17001'}), (v:Valve)
WHERE EXISTS { (f)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-20003'}),
      (v:PlantItem:Valve),
      (e:PlantItem:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-24501B'}), (v:Valve), (e:Equipment)
WHERE v.operating_position = 'NO'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (source:PlantItem {tag: 'P-23702A'}), (v:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (source:Equipment {tag: 'K-6701'}), (v:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'F-17001'}), (v:Valve)
WHERE (v.operating_position = 'NO' OR v.operating_position IS NULL)
  AND EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-20003'}), (v:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:GateValve {line_number: '6-P-2440010-B1A-N'})-[:line_to*1..]->(fe:PlantItem {tag: 'FE-245001'})
RETURN DISTINCT v.tag AS tag, v.line_number AS line_number, coalesce(v.operating_position, 'NO') AS normal_operating_position
ORDER BY tag, line_number, normal_operating_position;

MATCH (v:PlantItem:GateValve {line_number: '6-P-3570054-B1A-N'}), (x:PlantItem {tag: 'XV-358003'})
WHERE EXISTS { (v)-[:line_to*1..]->(x) }
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS operating_position

MATCH (v:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'E-24202'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve), (target:PlantItem {tag: 'EA-33401'})
WHERE (v)-[:line_to*1..]->(target)
  AND NOT (v:CheckValve OR v:GlobeCheckValve OR v:SwingCheckValve OR v:SafetyValveOrFitting OR v:SpringLoadedAngleGlobeSafetyValve OR v:SpringLoadedGlobeSafetyValve)
  AND NOT EXISTS { ()-[:control]->(v) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(tank:PlantItem {tag: 'TK-43801'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(r:PlantItem {tag: 'R-42901'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'K-13201'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
